#pragma once
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <functional>
#include <iostream>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

// Portable C++11 CPU reference model, not DirectXTK or a GPU renderer.
namespace fontlab {
struct Rect { int x, y, w, h; };
struct Glyph { char32_t codepoint; Rect atlas; float bearingX, bearingY, advance; };
struct Quad { char32_t codepoint; float x0,y0,x1,y1,u0,v0,u1,v1; };
struct Layout { std::vector<Quad> quads; float maxAdvance; unsigned lines; };
bool scalar(uint32_t cp) { return cp<=0x10ffffu && !(cp>=0xd800u&&cp<=0xdfffu); }
bool good(float v) { return std::isfinite(v)!=0; }
std::vector<char32_t> decode(const std::string& s) {
  std::vector<char32_t> result;
  for(size_t i=0;i<s.size();) {
    const uint8_t b=(uint8_t)s[i];
    unsigned n=0; uint32_t cp=0; uint32_t mincp=0;
    if(b<0x80) { n=1; cp=b; mincp=0; }
    else if(b>=0xc2&&b<=0xdf) { n=2; cp=b&0x1f; mincp=0x80; }
    else if(b>=0xe0&&b<=0xef) { n=3; cp=b&0x0f; mincp=0x800; }
    else if(b>=0xf0&&b<=0xf4) { n=4; cp=b&7; mincp=0x10000; }
    else throw std::invalid_argument("illegal UTF-8 leading byte");
    if(s.size()-i<n) throw std::invalid_argument("truncated UTF-8");
    for(unsigned j=1;j<n;++j) {
      uint8_t tail=(uint8_t)s[i+j];
      if((tail&0xc0)!=0x80) throw std::invalid_argument("illegal UTF-8 continuation");
      cp=(cp<<6)|(tail&0x3f);
    }
    if(cp<mincp||!scalar(cp)) throw std::invalid_argument("invalid UTF-8 scalar");
    result.push_back(static_cast<char32_t>(cp)); i+=n;
  }
  return result;
}
bool inside(Rect r,int w,int h) {
  return w>0&&h>0&&r.x>=0&&r.y>=0&&r.w>0&&
         r.x<w&&r.y<h&&r.w<=w-r.x&&r.h<=h-r.y;
}
bool overlap(Rect a,Rect b) {
  return a.x<b.x+b.w&&b.x<a.x+a.w&&a.y<b.y+b.h&&b.y<a.y+a.h;
}
class Atlas {
  int width_,height_; float lineHeight_;
  std::map<char32_t,Glyph> glyphs_;
public:
  Atlas(int w,int h,float line):width_(w),height_(h),lineHeight_(line) {
    if(w<=0||h<=0||!good(line)||line<=0) throw std::invalid_argument("invalid atlas");
  }
  void add(const Glyph& g) {
    if(!scalar((uint32_t)g.codepoint)||!inside(g.atlas,width_,height_)||
       !good(g.advance)||g.advance<=0||!good(g.bearingX)||!good(g.bearingY)||
       glyphs_.count(g.codepoint)) throw std::invalid_argument("invalid glyph");
    for(std::map<char32_t,Glyph>::const_iterator it=glyphs_.begin();it!=glyphs_.end();++it)
      if(overlap(g.atlas,it->second.atlas)) throw std::invalid_argument("overlapping atlas rectangles");
    glyphs_.insert(std::make_pair(g.codepoint,g));
  }
  Layout draw(const std::string& utf8,float size) const {
    if(!good(size)||size<=0) throw std::invalid_argument("invalid text size");
    const std::vector<char32_t> cp=decode(utf8);
    Layout out;out.maxAdvance=0;out.lines=1;
    float penX=0,penY=0;
    for(size_t i=0;i<cp.size();++i) {
      if(cp[i]==U'\n') {out.maxAdvance=std::max(out.maxAdvance,penX);penX=0;penY+=lineHeight_*size;++out.lines;continue;}
      if(cp[i]==U'\r') throw std::invalid_argument("CR must be normalized before layout");
      std::map<char32_t,Glyph>::const_iterator it=glyphs_.find(cp[i]);
      if(it==glyphs_.end()) it=glyphs_.find(U'?');
      if(it==glyphs_.end()) throw std::invalid_argument("missing glyph and fallback");
      const Glyph& g=it->second;
      Quad q={cp[i],penX+g.bearingX*size,penY+g.bearingY*size,
              penX+(g.bearingX+g.atlas.w)*size,penY+(g.bearingY+g.atlas.h)*size,
              float(g.atlas.x)/width_,float(g.atlas.y)/height_,
              float(g.atlas.x+g.atlas.w)/width_,float(g.atlas.y+g.atlas.h)/height_};
      out.quads.push_back(q);penX+=g.advance*size;
    }
    out.maxAdvance=std::max(out.maxAdvance,penX);return out;
  }
};
} // namespace fontlab

#include "fontlab.hpp"

static std::string bytes(std::initializer_list<int> seq) {
  std::string s;
  for(std::initializer_list<int>::const_iterator it=seq.begin();it!=seq.end();++it) s.push_back(static_cast<char>(*it));
  return s;
}

int main() {
  using namespace fontlab;
  unsigned n=0;
  const auto ck=[&](bool b,const char* why) {if(!b) throw std::runtime_error(why);++n;};
  const auto throws=[&](const std::function<void()>& fn) {try {fn();return false;}catch(const std::invalid_argument&){return true;}};
  ck(decode("").empty(),"utf8 empty");
  ck(decode("ABC").size()==3,"ascii");
  ck(decode("A")[0]==U'A',"ascii cp");
  ck(decode(bytes({0xc2,0xa2}))[0]==0xa2,"utf8 2 bytes");
  ck(decode(bytes({0xe2,0x82,0xac}))[0]==0x20ac,"utf8 3 bytes");
  ck(decode(bytes({0xf0,0x9f,0x98,0x80}))[0]==0x1f600,"utf8 4 bytes");
  ck(throws([]{decode(bytes({0x80}));}),"orphan continuation");
  ck(throws([]{decode(bytes({0xc0,0xaf}));}),"overlong 2");
  ck(throws([]{decode(bytes({0xe0,0x80,0x80}));}),"overlong 3");
  ck(throws([]{decode(bytes({0xf0,0x80,0x80,0x80}));}),"overlong 4");
  ck(throws([]{decode(bytes({0xed,0xa0,0x80}));}),"surrogate");
  ck(throws([]{decode(bytes({0xf4,0x90,0x80,0x80}));}),"above max");
  ck(throws([]{decode(bytes({0xf5,0x80,0x80,0x80}));}),"illegal head 5");
  ck(throws([]{decode(bytes({0xe2,0x82}));}),"truncated");
  ck(throws([]{decode(bytes({0xc2})+"A");}),"invalid continuation");
  ck(throws([]{decode(bytes({0xff}));}),"invalid FF");
  ck(scalar(0)&&scalar(0x10ffff),"scalar boundaries");
  ck(!scalar(0xd800)&&!scalar(0xdfff),"surrogate range");
  ck(!scalar(0x110000),"scalar upper");
  ck(inside({0,0,1,1},8,8),"inside origin");
  ck(inside({7,7,1,1},8,8),"inside edge");
  ck(!inside({7,7,2,1},8,8),"outside right");
  ck(!inside({0,0,0,1},8,8),"empty rect");
  ck(!overlap({0,0,2,2},{2,0,2,2}),"touching atlas border");
  ck(overlap({0,0,2,2},{1,1,2,2}),"overlap test");
  ck(throws([]{Atlas a(0,8,10);}),"invalid width");
  ck(throws([]{Atlas a(8,8,0);}),"invalid line");
  Atlas a(64,64,16);
  const Glyph ga={U'A',{0,0,8,10},0,2,9},gb={U'B',{8,0,8,10},0,2,9},gq={U'?',{16,0,8,10},0,2,9};
  a.add(ga);a.add(gb);a.add(gq);
  ck(throws([&]{a.add(ga);}),"duplicate glyph");
  ck(throws([&]{a.add({U'C',{7,0,2,10},0,2,9});}),"atlas overlap");
  ck(throws([&]{a.add({U'C',{63,0,2,2},0,2,9});}),"glyph out of atlas");
  ck(throws([&]{a.add({U'C',{32,0,8,10},0,2,0});}),"glyph zero advance");
  ck(throws([&]{a.add({U'C',{32,0,8,10},0,2,INFINITY});}),"glyph infinite advance");
  const Layout empty=a.draw("",1);
  ck(empty.lines==1&&empty.quads.empty()&&empty.maxAdvance==0,"empty layout");
  const Layout one=a.draw("A",1);
  ck(one.quads.size()==1&&one.lines==1,"one quad");
  ck(one.quads[0].x0==0&&one.quads[0].y0==2,"bearing");
  ck(one.quads[0].x1==8&&one.quads[0].y1==12,"pixel dimensions");
  ck(std::abs(one.quads[0].u1-0.125f)<0.0001f,"normalized UV");
  ck(one.maxAdvance==9,"advance");
  const Layout many=a.draw("AB",2);
  ck(many.quads.size()==2&&many.maxAdvance==36,"scaled advance");
  ck(many.quads[1].x0==18&&many.quads[1].y0==4,"second glyph pen");
  const Layout rows=a.draw("A\nB",1);
  ck(rows.lines==2&&rows.quads.size()==2,"line break");
  ck(rows.quads[1].y0==18&&rows.maxAdvance==9,"line height");
  ck(a.draw("Z",1).quads[0].u0==0.25f,"fallback atlas");
  ck(throws([&]{a.draw("A",0);}),"scale 0");
  ck(throws([&]{a.draw("A",INFINITY);}),"scale inf");
  ck(throws([&]{a.draw("A\rB",1);}),"CR normalization");
  ck(throws([&]{a.draw(bytes({0xc0,0xaf}),1);}),"UTF8 checked at layout");
  ck(a.draw("A\n",1).lines==2,"trailing newline");
  ck(a.draw("\n",1).quads.empty(),"newline no quad");
  std::cout<<"PASS "<<n<<" Font UTF-8 atlas layout CPU contract checks\n";
}
